  var normalizeEmail = function (value) { return String(value || '').trim().toLowerCase(); };
  var esc = function (value) { return String(value == null ? '' : value).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); };
  var url = function (value) { return encodeURIComponent(value); };
