  function balanced(source, limit) {
    var picked = [], used = new Set(), flagged = source.filter(function (p) { return p.bestSeller; });
    flagged.forEach(function (p) { if (picked.length < limit && !used.has(p.id)) { picked.push(p); used.add(p.id); } });
    var remaining = source.filter(function (p) { return !used.has(p.id); });
    var buckets = new Map();
    remaining.forEach(function (p) { var key = p.category || ''; if (!buckets.has(key)) buckets.set(key, []); buckets.get(key).push(p); });
    var keys = Array.from(buckets.keys());
    while (picked.length < limit && keys.length) {
      keys.forEach(function (key) { var p = buckets.get(key).shift(); if (p && picked.length < limit && !used.has(p.id)) { picked.push(p); used.add(p.id); } });
      keys = keys.filter(function (key) { return buckets.get(key).length; });
    }
    return picked;
  }
